138	
139	    if (payment.status === "refunded") {
140	      return errorResponse(409, "already_refunded", "Payment already refunded");
141	    }
142	    if (payment.status !== "succeeded" && payment.status !== "partially_refunded") {
143	      return errorResponse(409, "not_refundable", `A ${payment.status} payment cannot be refunded`);
144	    }
145	
146	    const body = (await request.json().catch(() => ({}))) as {
147	      amount?: number;
148	    };
149	    const remaining = payment.amount - payment.amountRefunded;
150	    const amount = body.amount ?? remaining;
151	
152	    if (!Number.isInteger(amount) || amount <= 0 || amount > remaining) {
153	      return errorResponse(
154	        422,
155	        "invalid_refund_amount",
156	        `Refund amount must be between 1 and ${remaining}`,
157	      );
158	    }
159	
160	    payment.amountRefunded += amount;
161	    payment.status = payment.amountRefunded === payment.amount ? "refunded" : "partially_refunded";
162	    return HttpResponse.json(payment);
163	  }),
164	
165	  // 5. Cancel a pending payment.
166	  http.post(`${BASE_URL}/payments/:id/cancel`, ({ request, params }) => {
167	    if (!isAuthorized(request)) {
168	      return unauthorized();
169	    }
170	    const payment = payments.get(params["id"] as string);
171	    if (!payment) {
172	      return notFound(params["id"] as string);
173	    }
174	
175	    if (payment.status !== "pending") {
176	      return errorResponse(409, "not_cancelable", `A ${payment.status} payment cannot be canceled`);
177	    }
178	
179	    payment.status = "canceled";
180	    return HttpResponse.json(payment);
181	  }),
