      ),
    );

    await expectApiError(client.getPayment("pay_x"), 502, "unknown_error", "Bad Gateway");
  });

  test("falls back to unknown_error when the JSON body has no error object", async () => {
    server.use(
      http.get(
        "https://api.example.com/v1/payments/pay_x",
