22	async function expectApiError(
23	  call: Promise<unknown>,
24	  expected: { status: number; code: string; message?: string },
25	) {
26	  await expect(call).rejects.toBeInstanceOf(PaymentsApiError);
27	  await expect(call).rejects.toMatchObject({
28	    name: "PaymentsApiError",
29	    status: expected.status,
30	    code: expected.code,
31	    ...(expected.message !== undefined && { message: expected.message }),
32	  });
33	}
